import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第119章 答案","description":"","frontmatter":{},"headers":[],"relativePath":"第119章_答案.md","filePath":"第119章_答案.md"}'),r={name:"第119章_答案.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第119章-答案" tabindex="-1">第119章 答案 <a class="header-anchor" href="#第119章-答案" aria-label="Permalink to &quot;第119章 答案&quot;">​</a></h1><p>我是沈聿。</p><p>收拾东西是在深夜，楼道很静，我把纸箱摊在地板中央，一样一样清理，像在和旧时光逐一道别。纸箱放在旧楼三楼的屋里，箱口用胶带封着，胶带已经黄了，一角翘起来。</p><p>我先用指甲把胶带一角挑起来，慢慢往回撕，胶带绷紧发出细细的嘶声，黏性还在，撕一下停一下，怕把箱口撕破。撕开后，灰就起来了，细细的灰在灯光里飘，像落了层薄雾，落在手背上凉凉的，一吹就散，闻着有淡淡的纸霉味。</p><p>最先露出来的是那台随身听，机身磨旧，边角磨得发亮，耳机线缠了几圈，上面系着一枚小小的平安结。红绳微褪，绳头有点散，绳结打得用心。那是我照着奶奶的法子编的，被退回后我自己戴着，一直系在随身听上，绳眼紧紧的。我用指腹摩挲那枚结，绳面有点毛，摩着指纹有点刺，心口轻轻发烫。</p><p>旁边放着几盘磁带，标签上的字是我先写，江苒又描过一遍，字迹叠着，边角起毛。有一盘转动时会发涩，歌声断续，可当年我们听得入迷。天台的风，熄灯前的教室，放学并肩走过的坡路，都藏在旋律里。我把磁带一盘盘拿出来，用绒布擦净，布面蹭过标签有轻响，逐盘装盒，盒盖合上咔哒一声。</p><p>窗外的雾很薄，贴在玻璃上，像一层纱，灯光透过去晕成一团，风一吹，雾就动。</p><p>还有一只玻璃罐，满满一罐纸星星，折得稚拙，边角并不齐整，旁人折的都不算在内，只有那二十七颗，和后来她新折的一颗。我和她伏在桌前折了许多个夜晚，纸条在指尖卷一下往里一扣就鼓起来，指尖发酸，心里却暖。星星纸在灯下闪着细碎的光，摇一晃哗啦响。好运是否来过，我已记不清，只记得灯下星星纸细碎的光和指腹被纸角硌得有点疼。</p><p>箱底躺着一根旧发带，颜色淡旧，边缘起毛。那是她跑步束发用的，有次落在我桌上，我顺手收起，她没催，我也没还。许多心照不宣的小事，便这样安放至今。发带上似还留着皂香，干净而遥远，摸着软软的，边有点卷。</p><p>箱子里没有那部小说的稿子。写好的那份，一份烧了，一份托温棠带走了。剩下的都是零碎，一件一件，都指向同一个人。</p><p>我把这些东西一件一件摆开，灯光落在上面，掌心摸着是凉的。熬夜写下的夜晚，反复涂改的段落，写到她笑起来便跟着开心的瞬间，一齐漫上来。我喜欢过她，这点清楚如掌纹。自她笑着把纸星星递给我那天，自她靠着我分戴一只耳机那天，自她垂首折星星那天，我的心动便已分明。</p><p>然而，没能一起走下去，同样是真的。</p><p>说开是在天台，云走得慢，有鸽子掠过。江苒抱膝坐着，轻声说，我们都很好，只是路不同了。我点头说我明白。我们没有争执，连难过都很安静。喜欢并未变质，只是时间将我们带往岔口。她有她的坚持，我有我的责任。靠近过，迁就过，有些距离终究靠用力补不上。</p><p>周野来帮我搬箱子，在屋里站了一会儿，看着地上那些零碎，问，都处置干净了。我说，烧的烧了，送的送了，就剩这些。烧那份的时候我蹲在铁盆前，看纸边一点一点往里卷，像折星星时纸在指尖收口。火熄了，他在旁边站到灰凉透，什么也没说。他一向如此，话少，却总在要紧处搭手。</p><p>温棠抱着胶带进门，望着星星罐问还留吗，我说留，留着，不动。她又看向发带，问要不要包好，我点头。她将发带叠齐，用纸裹好，放进箱中柔软角落，动作放得很轻，纸角折得齐齐的。</p><p>温棠走近，把玻璃罐塞回我怀里，说暖的东西要留着，星星的光要留着。我抱紧点头，玻璃凉凉的，星星在里面轻晃。</p><p>这一箱，是纪念。不为重温，不为示人，只为证明存在过，证明我认真喜欢过，也认真写完过。封存，是给过去体面，给未来留白。绳头垂在箱沿，我用指腹理了理，让它顺顺地垂着。</p><p>江苒发来一句，问收拾得如何，我说快好了。她笑说随身听要留好，以后还能听，磁带别弄丢。我说平安结还在，没松，一直系着。她顿了顿，轻声道谢。我说，也谢谢你，谢谢那段日子。</p><p>我们都没提重来，默契如约好那般。因为我们都懂，答案不在重逢里。</p><p>我把随身听擦净摆正，平安结理好，与磁带同放，绳头顺下来。临装箱前，我戴上耳机，按下播放键，熟悉的前奏混着轻微的底噪漫出来，沙沙的。江苒曾在这首歌里跟着哼，调子跑远了，自己先笑起来。周野笑她，她便拉温棠下水，温棠摆手求饶，屋里笑作一团，碗筷轻响。那时的快乐很简单，一盘带子便能撑起整晚。如今再听，歌还在，人已各有去处，我却不再觉得疼，只觉得谢谢。谢那段被歌声托住的日子，谢她们陪我走过青涩。</p><p>发带包妥，星星罐裹妥，灰掸净了，绳头理好了。合箱时一声轻响，像句点落定，胶带拉直绷紧的声音很脆。</p><p>周野帮我封箱，胶带拉直，说往前走吧。我说好。温棠立在门口，眼圈微红却笑着，说你要写新故事了。我点头，说会写，写更坦荡的故事。</p><p>屋子重归安静，我坐在地板上望着纸箱，觉得胸口松快。窗外的雾还在，薄薄一层贴在玻璃上，风一吹，雾就散一点又聚一点。灰已经掸掉，绳头已经理顺，箱子安稳地立在墙角。</p><p>周野临走时说的话还在耳边，他说放下方能走远。温棠出门前回头看了我一眼，目光温软，带着祝福。我忽然明白，告别并非将人推远，是把位置还给各自的人生。此后提起江苒，我仍会笑，仍会记得平安结的红，星星的光，发带的旧，磁带的响。记得，却不再拉扯。喜欢过，是真心。没能走下去，是事实。两者并存，都值得承认。</p><p>江苒很好，会耐心折完星星，会陪我听完整盘磁带，会在灯下把纸星星的角折得齐齐的。我喜欢她，想把好歌都存给她，想为她写很长的故事。可喜欢抵不过方向不同。我们看过同一片云，终究走向不同路。这并不可怨，只是成长的模样。</p><p>我在本上写下答案，字迹平稳。这份答案无关重逢，只关于放下。将人还给远方，将心还给日子，愿她平安，愿我坦荡，各自把路走好。</p><p>天色渐淡，雾也淡了，我合上本子。随身听安睡，平安结静系，磁带静卧，星星静闪。一份稿子随风而去，一份稿子随岁月而留。灰落定了，绳头垂稳了，窗外的雾慢慢散开。</p><p>我是沈聿，这道答案，我写完了。</p>',28)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
